        make_gmem_ptr(b_ptr),
        make_shape(OC),
        make_stride(1));

    extern __shared__ float smem[];
    auto sX = make_tensor(
        make_smem_ptr(smem),
        make_shape(IC_TILE, TILE + K - 1, TILE + K - 1, TILE + K - 1),
        make_stride((TILE + K - 1) * (TILE + K - 1) * (TILE + K - 1),
